// src/App.jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { motion } from "framer-motion";

export default function App() {
  // -----------------------------
  // THEME (persistent)
  // -----------------------------
  const [dark, setDark] = useState(false);

  // initialize theme from localStorage or system preference
  useEffect(() => {
    const stored = localStorage.getItem("theme");
    if (stored) {
      setDark(stored === "dark");
    } else {
      const prefersDark = window.matchMedia?.("(prefers-color-scheme: dark)").matches;
      setDark(prefersDark);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem("theme", dark ? "dark" : "light");
  }, [dark]);

  const toggleTheme = () => setDark((d) => !d);

  // -----------------------------
  // NAV (hamburger + scroll spy)
  // -----------------------------
  const [menuOpen, setMenuOpen] = useState(false);
  const [active, setActive] = useState("home");

  const sectionIds = useMemo(
    () => ["home", "about", "vision", "projects", "skills", "timeline", "papers", "news", "blog"],
    []
  );

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        // pick the entry most in view
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible?.target?.id) setActive(visible.target.id);
      },
      { root: null, rootMargin: "0px 0px -60% 0px", threshold: [0.2, 0.4, 0.6, 0.8] }
    );

    sectionIds.forEach((id) => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [sectionIds]);

  // -----------------------------
  // Background parallax glow
  // -----------------------------
  const [mouse, setMouse] = useState({ x: 0, y: 0 });
  const glowRef = useRef(null);

  useEffect(() => {
    function onMove(e) {
      setMouse({ x: e.clientX, y: e.clientY });
    }
    window.addEventListener("mousemove", onMove);
    return () => window.removeEventListener("mousemove", onMove);
  }, []);

  // compute slight parallax transform
  const parallax1 = {
    transform: `translate(${(mouse.x - window.innerWidth / 2) * 0.02}px, ${
      (mouse.y - window.innerHeight / 2) * 0.02
    }px)`,
  };
  const parallax2 = {
    transform: `translate(${(window.innerWidth / 2 - mouse.x) * 0.015}px, ${
      (window.innerHeight / 2 - mouse.y) * 0.015
    }px)`,
  };

  // -----------------------------
  // Motion helper
  // -----------------------------
  const fadeUp = {
    initial: { opacity: 0, y: 16 },
    whileInView: { opacity: 1, y: 0 },
    transition: { duration: 0.5, ease: "easeOut" },
    viewport: { once: true, amount: 0.3 },
  };

  return (
    <div className={dark ? "dark" : ""}>
      {/* page wrap with theme colors */}
      <motion.div
        className="min-h-screen transition-colors duration-500 bg-neutral-50 text-neutral-800 dark:bg-neutral-950 dark:text-neutral-100"
        animate={{ opacity: 1 }}
        initial={{ opacity: 0.98 }}
        transition={{ duration: 0.35 }}
      >
        {/* Background Glows (futuristic) */}
        <div
          ref={glowRef}
          className="fixed inset-0 -z-10 select-none pointer-events-none will-change-transform"
          aria-hidden
        >
          <div
            style={parallax1}
            className="absolute w-[60vw] h-[60vw] max-w-[900px] max-h-[900px] bg-cyan-400/20 blur-[90px] rounded-full -top-32 -left-32 transition-transform duration-300"
          />
          <div
            style={parallax2}
            className="absolute w-[50vw] h-[50vw] max-w-[700px] max-h-[700px] bg-fuchsia-400/15 blur-[110px] rounded-full -bottom-24 -right-24 transition-transform duration-300"
          />
        </div>

        {/* NAVBAR */}
        <header className="sticky top-0 z-50 backdrop-blur-xl bg-neutral-900/50 border-b border-neutral-800 dark:bg-neutral-900/50">
          <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
            <a href="#home" className="font-semibold tracking-tight text-lg md:text-xl">
              Khalil Braham
            </a>

            {/* Desktop nav */}
            <nav className="hidden md:flex items-center gap-6 text-sm">
              {sectionIds.map((id) => (
                <a
                  key={id}
                  href={`#${id}`}
                  className={
                    active === id
                      ? "text-cyan-400"
                      : "text-neutral-200/80 hover:text-cyan-300 dark:text-neutral-200/80"
                  }
                >
                  {id.toUpperCase()}
                </a>
              ))}
            </nav>

            {/* Controls */}
            <div className="flex items-center gap-2">
              <button
                onClick={() => setMenuOpen((o) => !o)}
                className="md:hidden px-3 py-2 rounded bg-neutral-800 text-neutral-100"
                aria-label="Open menu"
              >
                ☰
              </button>
              <button
                onClick={toggleTheme}
                className="px-3 py-2 rounded shadow-[0_0_10px_#22d3ee] hover:shadow-[0_0_18px_#22d3ee] transition-all duration-300 bg-neutral-200 text-neutral-800 dark:bg-neutral-700 dark:text-neutral-200"
                aria-label="Toggle theme"
              >
                {dark ? "Light" : "Dark"}
              </button>
            </div>
          </div>

          {/* Mobile menu */}
          {menuOpen && (
            <div className="md:hidden flex flex-col bg-neutral-900/90 px-6 py-4 text-sm gap-3 border-t border-neutral-800">
              {sectionIds.map((id) => (
                <a
                  key={id}
                  href={`#${id}`}
                  onClick={() => setMenuOpen(false)}
                  className={active === id ? "text-cyan-400" : "hover:text-cyan-300 text-neutral-200"}
                >
                  {id.toUpperCase()}
                </a>
              ))}
            </div>
          )}
        </header>

        {/* HERO */}
        <section id="home" className="max-w-6xl mx-auto text-center pt-28 pb-16 md:pt-32 md:pb-20 px-6">
          <motion.h1
            initial={{ opacity: 0, y: 18 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="text-4xl md:text-5xl font-bold"
          >
            Generative AI & LLMs for Scientific Intelligence
          </motion.h1>
          <p className="mt-4 opacity-80 text-base md:text-lg">
            Diffusion • Flow Matching • Alignment • Drug Discovery Applications
          </p>
          <div className="mt-6 flex justify-center gap-3">
            <a
              href="#vision"
              className="px-4 py-2 rounded-full bg-neutral-900 text-white dark:bg-white dark:text-neutral-900 text-sm shadow hover:opacity-90 transition"
            >
              Research Vision
            </a>
            <a
              href="/cv.pdf"
              className="px-4 py-2 rounded-full border border-neutral-300 dark:border-neutral-700 text-sm hover:bg-neutral-900/5 dark:hover:bg-white/5 transition"
            >
              Download CV
            </a>
          </div>
        </section>

        {/* ABOUT */}
        <section id="about" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            About
          </motion.h2>
          <motion.p {...fadeUp} className="mt-4 leading-relaxed opacity-90">
            Researching generative modeling and LLMs across discrete scientific domains (molecules, biology, code).
            Collaboration with Sanofi on pharmacology LLM alignment. Formerly at École Polytechnique & Inria Saclay.
          </motion.p>
        </section>

        {/* VISION */}
        <section id="vision" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Research Vision
          </motion.h2>
          <motion.p {...fadeUp} className="mt-4 leading-relaxed opacity-90">
            Building autonomous scientific agents capable of proposing experiments, refining molecular candidates, and
            interacting with literature via tools, retrieval-augmented reasoning, and alignment.
          </motion.p>
        </section>

        {/* PROJECTS */}
        <section id="projects" className="max-w-6xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Research Projects
          </motion.h2>
          <div className="grid md:grid-cols-3 gap-6 mt-6">
            {[
              {
                title: "Flow-Matching for Molecules",
                desc: "Graph-conditioned generation; structure validity; controllable sampling.",
              },
              {
                title: "LLM Agents for Science",
                desc: "Tool-use, planning, evaluation loops for experimental design.",
              },
              {
                title: "Graph Diffusion for Drug Candidates",
                desc: "Property-aware generation; docking-in-the-loop workflows.",
              },
            ].map((p) => (
              <motion.div
                key={p.title}
                whileHover={{ scale: 1.03 }}
                className="p-5 bg-neutral-900/40 border border-neutral-800 rounded-xl"
              >
                <h3 className="font-semibold text-lg mb-2">{p.title}</h3>
                <p className="opacity-75 text-sm">{p.desc}</p>
              </motion.div>
            ))}
          </div>
        </section>

        {/* SKILLS */}
        <section id="skills" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Skills
          </motion.h2>
          <div className="flex flex-wrap gap-2 mt-6">
            {[
              "PyTorch",
              "RAG",
              "Diffusion Models",
              "Flow Matching",
              "RLHF",
              "Molecular Modeling",
              "Graph ML",
              "Attention",
              "Optimization",
              "CUDA",
              "Linux",
              "MLOps",
            ].map((s) => (
              <span
                key={s}
                className="px-3 py-1 rounded-full bg-cyan-500/20 border border-cyan-400/30 text-sm"
              >
                {s}
              </span>
            ))}
          </div>
        </section>

        {/* TIMELINE */}
        <section id="timeline" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Experience & Milestones
          </motion.h2>
          <div className="border-l border-neutral-700 ml-4 mt-6 space-y-6">
            {[
              ["2025–", "Polytechnique & Inria — Discrete generative modeling"],
              ["2024–2025", "Sanofi — LLM pharmacology alignment"],
              ["2023–2024", "Retail analytics — Time-series shape modeling"],
            ].map(([date, desc]) => (
              <div key={date} className="pl-6 relative">
                <div className="w-3 h-3 bg-cyan-400 rounded-full absolute -left-[7px] top-1.5" />
                <p className="text-sm opacity-70">{date}</p>
                <p className="text-base">{desc}</p>
              </div>
            ))}
          </div>
        </section>

        {/* PAPERS */}
        <section id="papers" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Selected Publications
          </motion.h2>
          <p className="mt-4 opacity-60">BibTeX ingestion coming.</p>
        </section>

        {/* NEWS */}
        <section id="news" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            News
          </motion.h2>
          <ul className="mt-4 opacity-85 list-disc pl-6 space-y-1">
            <li>2025 — Starting collaboration with Sanofi.</li>
            <li>2025 — Experiments with flow-matching on molecular graphs.</li>
          </ul>
        </section>

        {/* BLOG */}
        <section id="blog" className="max-w-5xl mx-auto py-16 px-6">
          <motion.h2 {...fadeUp} className="text-3xl font-semibold">
            Blog Notes
          </motion.h2>
          <ul className="mt-4 opacity-85 list-disc pl-6 space-y-1">
            <li>Agentic reasoning for science.</li>
            <li>Symbolic constraints in molecular diffusion.</li>
          </ul>
        </section>

        {/* FOOTER */}
        <footer className="py-12 text-center opacity-60 text-sm">
          © {new Date().getFullYear()} — Khalil Braham
        </footer>
      </motion.div>
    </div>
  );
}
